values (
  'en-the-beatles-trivia',
  'The Beatles Trivia Challenge',
  'From Liverpool''s Cavern Club to the Abbey Road crossing: four lads who changed pop music forever. How much do you know about the Fab Four?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"In which English city did The Beatles form?","options":[{"id":"a","text":"Manchester","is_correct":false},{"id":"b","text":"London","is_correct":false},{"id":"c","text":"Liverpool","is_correct":true},{"id":"d","text":"Birmingham","is_correct":false}],"explanation":"The band came together in Liverpool, where the Cavern Club became their early home."},{"id":"q2","question":"Who was The Beatles'' drummer during their years of fame?","options":[{"id":"a","text":"Pete Best","is_correct":false},{"id":"b","text":"Ringo Starr","is_correct":true},{"id":"c","text":"Stuart Sutcliffe","is_correct":false},{"id":"d","text":"George Martin","is_correct":false}],"explanation":"Ringo Starr replaced original drummer Pete Best in August 1962; Sutcliffe played bass early on and Martin was the producer."},{"id":"q3","question":"Which album cover shows the four of them crossing a zebra crossing?","options":[{"id":"a","text":"Sgt. Pepper''s Lonely Hearts Club Band","is_correct":false},{"id":"b","text":"Revolver","is_correct":false},{"id":"c","text":"Let It Be","is_correct":false},{"id":"d","text":"Abbey Road","is_correct":true}],"explanation":"The Abbey Road cover was shot on the street outside the studio; the crossing is still a tourist attraction."},{"id":"q4","question":"Who produced nearly all of The Beatles'' records and is often called ''the fifth Beatle''?","options":[{"id":"a","text":"George Martin","is_correct":true},{"id":"b","text":"Brian Epstein","is_correct":false},{"id":"c","text":"Phil Spector","is_correct":false},{"id":"d","text":"George Harrison","is_correct":false}],"explanation":"George Martin signed them to Parlophone and shaped their studio sound; Epstein was the manager and Spector only finished Let It Be."},{"id":"q5","question":"Paul McCartney wrote ''Hey Jude'' to comfort whom?","options":[{"id":"a","text":"John Lennon''s mother Julia","is_correct":false},{"id":"b","text":"His own daughter Mary","is_correct":false},{"id":"c","text":"John Lennon''s son Julian","is_correct":true},{"id":"d","text":"A fan named Judy","is_correct":false}],"explanation":"He wrote it as ''Hey Jules'' for five-year-old Julian during John and Cynthia Lennon''s divorce."},{"id":"q6","question":"Which was the last studio album The Beatles recorded together?","options":[{"id":"a","text":"The White Album","is_correct":false},{"id":"b","text":"Abbey Road","is_correct":true},{"id":"c","text":"Let It Be","is_correct":false},{"id":"d","text":"Magical Mystery Tour","is_correct":false}],"explanation":"Abbey Road was recorded in mid-1969; Let It Be came out later, in 1970, but had been recorded earlier."},{"id":"q7","question":"Where did The Beatles give their famous final live performance in January 1969?","options":[{"id":"a","text":"Shea Stadium, New York","is_correct":false},{"id":"b","text":"The Cavern Club","is_correct":false},{"id":"c","text":"The Ed Sullivan Show","is_correct":false},{"id":"d","text":"The rooftop of the Apple Corps building","is_correct":true}],"explanation":"On 30 January 1969 they played an unannounced concert on the roof of 3 Savile Row in London until the police shut it down."},{"id":"q8","question":"Which 1967 album introduces a fictional band and includes ''Lucy in the Sky with Diamonds''?","options":[{"id":"a","text":"Sgt. Pepper''s Lonely Hearts Club Band","is_correct":true},{"id":"b","text":"Rubber Soul","is_correct":false},{"id":"c","text":"Revolver","is_correct":false},{"id":"d","text":"The White Album","is_correct":false}],"explanation":"Sgt. Pepper''s presented the Beatles as an alter-ego band and became a landmark of psychedelic rock."}]'::jsonb,
  null,
  array['the beatles', 'music', 'rock', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
