values (
  'es-trivia-the-beatles',
  'Trivia de The Beatles',
  'De la Cavern Club de Liverpool al paso de cebra de Abbey Road: el grupo que cambió la música pop para siempre. ¿Cuánto sabes de los Fab Four?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"¿De qué ciudad inglesa son The Beatles?","options":[{"id":"a","text":"Liverpool","is_correct":true},{"id":"b","text":"Mánchester","is_correct":false},{"id":"c","text":"Londres","is_correct":false},{"id":"d","text":"Leeds","is_correct":false}],"explanation":"Se formaron en Liverpool, donde el club The Cavern fue su primer escenario habitual."},{"id":"q2","question":"¿Cuál es el verdadero nombre de Ringo Starr?","options":[{"id":"a","text":"Roger Taylor","is_correct":false},{"id":"b","text":"Reginald Dwight","is_correct":false},{"id":"c","text":"Richard Starkey","is_correct":true},{"id":"d","text":"Robert Plant","is_correct":false}],"explanation":"Ringo Starr nació como Richard Starkey; Reginald Dwight es Elton John, Taylor el baterista de Queen y Plant el cantante de Led Zeppelin."},{"id":"q3","question":"¿En qué año se separó oficialmente el grupo?","options":[{"id":"a","text":"1968","is_correct":false},{"id":"b","text":"1973","is_correct":false},{"id":"c","text":"1975","is_correct":false},{"id":"d","text":"1970","is_correct":true}],"explanation":"Paul McCartney anunció su salida en abril de 1970 y Let It Be salió un mes después."},{"id":"q4","question":"¿Qué canción de Abbey Road compuso George Harrison?","options":[{"id":"a","text":"''Come Together''","is_correct":false},{"id":"b","text":"''Here Comes the Sun''","is_correct":true},{"id":"c","text":"''I Am the Walrus''","is_correct":false},{"id":"d","text":"''Get Back''","is_correct":false}],"explanation":"Harrison la escribió en el jardín de Eric Clapton; en el mismo disco también firmó ''Something''."},{"id":"q5","question":"¿Qué hicieron los Beatles el 30 de enero de 1969?","options":[{"id":"a","text":"Lanzaron Let It Be","is_correct":false},{"id":"b","text":"Aparecieron en el Ed Sullivan Show","is_correct":false},{"id":"c","text":"Tocaron por última vez en vivo, en la azotea de Apple","is_correct":true},{"id":"d","text":"Grabaron ''Hey Jude''","is_correct":false}],"explanation":"Fue el célebre concierto de la azotea en Savile Row, interrumpido por la policía."},{"id":"q6","question":"¿Cómo se llamaba la discográfica que el grupo fundó en 1968?","options":[{"id":"a","text":"Parlophone","is_correct":false},{"id":"b","text":"Decca","is_correct":false},{"id":"c","text":"Apple Corps","is_correct":true},{"id":"d","text":"Capitol","is_correct":false}],"explanation":"Apple Corps editó sus discos desde 1968; Parlophone era su sello dentro de EMI y Decca los había rechazado en 1962."},{"id":"q7","question":"¿Qué álbum de 1967 presenta a una banda ficticia como alter ego del grupo?","options":[{"id":"a","text":"Revolver","is_correct":false},{"id":"b","text":"Sgt. Pepper''s Lonely Hearts Club Band","is_correct":true},{"id":"c","text":"Rubber Soul","is_correct":false},{"id":"d","text":"Magical Mystery Tour","is_correct":false}],"explanation":"Sgt. Pepper''s los presentaba como otra banda y marcó un hito del rock psicodélico."},{"id":"q8","question":"¿Cuál es la canción de los Beatles más versionada de la historia?","options":[{"id":"a","text":"''Yesterday''","is_correct":true},{"id":"b","text":"''Hey Jude''","is_correct":false},{"id":"c","text":"''Let It Be''","is_correct":false},{"id":"d","text":"''Twist and Shout''","is_correct":false}],"explanation":"''Yesterday'', compuesta por Paul McCartney, figura en el libro Guinness como la canción más versionada."}]'::jsonb,
  null,
  array['the beatles', 'musica', 'rock', 'trivia']::text[],
  3,
  'published',
