values (
  'en-elvis-presley-trivia',
  'Elvis Presley Trivia Challenge',
  'From a two-room house in Tupelo to Graceland and Las Vegas: the King of Rock and Roll''s life in questions. Can you keep up with Elvis?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"In which Mississippi town was Elvis born in 1935?","options":[{"id":"a","text":"Memphis","is_correct":false},{"id":"b","text":"Jackson","is_correct":false},{"id":"c","text":"Tupelo","is_correct":true},{"id":"d","text":"Nashville","is_correct":false}],"explanation":"He was born in Tupelo and moved to Memphis, Tennessee, as a teenager."},{"id":"q2","question":"What is the name of Elvis''s Memphis mansion, now open to the public?","options":[{"id":"a","text":"Graceland","is_correct":true},{"id":"b","text":"Heartbreak Hotel","is_correct":false},{"id":"c","text":"Neverland","is_correct":false},{"id":"d","text":"Sun Villa","is_correct":false}],"explanation":"Elvis bought Graceland in 1957; it is now a museum and one of the most visited homes in the United States."},{"id":"q3","question":"Which 1956 single gave Elvis his first No. 1 on the US pop chart?","options":[{"id":"a","text":"''Hound Dog''","is_correct":false},{"id":"b","text":"''Jailhouse Rock''","is_correct":false},{"id":"c","text":"''That''s All Right''","is_correct":false},{"id":"d","text":"''Heartbreak Hotel''","is_correct":true}],"explanation":"''Heartbreak Hotel'' topped the chart in April 1956; ''That''s All Right'' was his first single but only a local hit."},{"id":"q4","question":"Which small Memphis label, run by Sam Phillips, first recorded Elvis?","options":[{"id":"a","text":"Stax","is_correct":false},{"id":"b","text":"Sun Records","is_correct":true},{"id":"c","text":"Motown","is_correct":false},{"id":"d","text":"RCA Victor","is_correct":false}],"explanation":"Sam Phillips''s Sun Records released his first singles in 1954; RCA Victor bought his contract a year later."},{"id":"q5","question":"Where was Elvis stationed during his US Army service (1958–1960)?","options":[{"id":"a","text":"Korea","is_correct":false},{"id":"b","text":"Hawaii","is_correct":false},{"id":"c","text":"Germany","is_correct":true},{"id":"d","text":"Japan","is_correct":false}],"explanation":"He served in Friedberg, West Germany, where he met Priscilla Beaulieu."},{"id":"q6","question":"In which 1957 film does Elvis play a convict who becomes a singer?","options":[{"id":"a","text":"Love Me Tender","is_correct":false},{"id":"b","text":"Blue Hawaii","is_correct":false},{"id":"c","text":"Viva Las Vegas","is_correct":false},{"id":"d","text":"Jailhouse Rock","is_correct":true}],"explanation":"Jailhouse Rock''s title-song dance sequence is one of the most famous scenes in his film career."},{"id":"q7","question":"What was Elvis''s televised 1968 return to live performance known as?","options":[{"id":"a","text":"Aloha from Hawaii","is_correct":false},{"id":"b","text":"The ''68 Comeback Special","is_correct":true},{"id":"c","text":"Elvis in Concert","is_correct":false},{"id":"d","text":"That''s the Way It Is","is_correct":false}],"explanation":"The NBC special aired in December 1968; Aloha from Hawaii came five years later, in 1973."},{"id":"q8","question":"Which 1969 single was Elvis''s last No. 1 on the Billboard Hot 100?","options":[{"id":"a","text":"''Can''t Help Falling in Love''","is_correct":false},{"id":"b","text":"''Burning Love''","is_correct":false},{"id":"c","text":"''Suspicious Minds''","is_correct":true},{"id":"d","text":"''Are You Lonesome Tonight?''","is_correct":false}],"explanation":"''Suspicious Minds'' hit No. 1 in November 1969; ''Burning Love'' (1972) peaked at No. 2."}]'::jsonb,
  null,
  array['elvis presley', 'music', 'rock', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
