  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"¿En qué ciudad nació Elvis en 1935?","options":[{"id":"a","text":"Memphis","is_correct":false},{"id":"b","text":"Tupelo","is_correct":true},{"id":"c","text":"Nashville","is_correct":false},{"id":"d","text":"Nueva Orleans","is_correct":false}],"explanation":"Nació en Tupelo, Misisipi, y de adolescente se mudó con su familia a Memphis, Tennessee."},{"id":"q2","question":"¿Cómo se llama la mansión de Elvis en Memphis, hoy abierta al público?","options":[{"id":"a","text":"Neverland","is_correct":false},{"id":"b","text":"Heartbreak Hotel","is_correct":false},{"id":"c","text":"Graceland","is_correct":true},{"id":"d","text":"Sun Villa","is_correct":false}],"explanation":"Elvis compró Graceland en 1957; hoy es museo y una de las casas más visitadas de Estados Unidos."},{"id":"q3","question":"¿En qué pequeño sello de Memphis, dirigido por Sam Phillips, grabó Elvis sus primeros discos?","options":[{"id":"a","text":"Stax","is_correct":false},{"id":"b","text":"RCA Victor","is_correct":false},{"id":"c","text":"Motown","is_correct":false},{"id":"d","text":"Sun Records","is_correct":true}],"explanation":"Sun Records lanzó sus primeros sencillos en 1954; RCA Victor le compró el contrato un año después."},{"id":"q4","question":"¿Qué canción le dio su primer número 1 en Estados Unidos en 1956?","options":[{"id":"a","text":"''Heartbreak Hotel''","is_correct":true},{"id":"b","text":"''Hound Dog''","is_correct":false},{"id":"c","text":"''Love Me Tender''","is_correct":false},{"id":"d","text":"''All Shook Up''","is_correct":false}],"explanation":"''Heartbreak Hotel'' llegó al número 1 en abril de 1956 y abrió su etapa en RCA."},{"id":"q5","question":"¿Dónde cumplió Elvis su servicio militar entre 1958 y 1960?","options":[{"id":"a","text":"En Corea","is_correct":false},{"id":"b","text":"En Alemania","is_correct":true},{"id":"c","text":"En Hawái","is_correct":false},{"id":"d","text":"En Japón","is_correct":false}],"explanation":"Sirvió en Friedberg, en la entonces Alemania Occidental."},{"id":"q6","question":"¿Cómo se llamaba su representante, conocido como ''el Coronel''?","options":[{"id":"a","text":"Brian Epstein","is_correct":false},{"id":"b","text":"Sam Phillips","is_correct":false},{"id":"c","text":"Coronel Sanders","is_correct":false},{"id":"d","text":"Coronel Tom Parker","is_correct":true}],"explanation":"El Coronel Tom Parker dirigió su carrera desde 1955; Epstein manejaba a los Beatles y Phillips fue quien lo descubrió."},{"id":"q7","question":"¿En qué película de 1961, ambientada en Hawái, canta ''Can''t Help Falling in Love''?","options":[{"id":"a","text":"Viva Las Vegas","is_correct":false},{"id":"b","text":"Blue Hawaii","is_correct":true},{"id":"c","text":"Girls! Girls! Girls!","is_correct":false},{"id":"d","text":"Fun in Acapulco","is_correct":false}],"explanation":"Blue Hawaii fue su película más taquillera y consolidó su etapa de comedias musicales exóticas."},{"id":"q8","question":"¿En qué año murió Elvis en Graceland?","options":[{"id":"a","text":"1969","is_correct":false},{"id":"b","text":"1974","is_correct":false},{"id":"c","text":"1980","is_correct":false},{"id":"d","text":"1977","is_correct":true}],"explanation":"Murió en Graceland el 16 de agosto de 1977, a los 42 años."}]'::jsonb,
