values (
  'en-madonna-trivia',
  'Madonna Trivia Challenge',
  'Four decades of reinvention, hit albums and record-breaking tours from the Queen of Pop. How well do you know Madonna''s music?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'music'),
  '[{"id":"q1","question":"In which US state was Madonna born?","options":[{"id":"a","text":"New York","is_correct":false},{"id":"b","text":"California","is_correct":false},{"id":"c","text":"Michigan","is_correct":true},{"id":"d","text":"Illinois","is_correct":false}],"explanation":"She was born in Bay City, Michigan, in 1958 and moved to New York in the late 1970s."},{"id":"q2","question":"Which 1984 album and single turned Madonna into a superstar?","options":[{"id":"a","text":"Like a Virgin","is_correct":true},{"id":"b","text":"Madonna","is_correct":false},{"id":"c","text":"True Blue","is_correct":false},{"id":"d","text":"Like a Prayer","is_correct":false}],"explanation":"Like a Virgin was her first No. 1 album and single, boosted by her famous MTV performance in a wedding dress."},{"id":"q3","question":"Which 1990 single popularized the ballroom-inspired dance style it is named after?","options":[{"id":"a","text":"''Express Yourself''","is_correct":false},{"id":"b","text":"''Vogue''","is_correct":true},{"id":"c","text":"''Justify My Love''","is_correct":false},{"id":"d","text":"''Ray of Light''","is_correct":false}],"explanation":"''Vogue'' took New York''s ballroom culture to the top of the charts worldwide."},{"id":"q4","question":"For which film role did Madonna win a Golden Globe for best actress?","options":[{"id":"a","text":"Breathless Mahoney in Dick Tracy","is_correct":false},{"id":"b","text":"Susan in Desperately Seeking Susan","is_correct":false},{"id":"c","text":"Eva Perón in Evita","is_correct":true},{"id":"d","text":"A baseball player in A League of Their Own","is_correct":false}],"explanation":"She won the 1997 Golden Globe for playing Eva Perón in the film version of the musical Evita."},{"id":"q5","question":"Which 1998 electronica-influenced album includes ''Frozen''?","options":[{"id":"a","text":"Music","is_correct":false},{"id":"b","text":"Bedtime Stories","is_correct":false},{"id":"c","text":"American Life","is_correct":false},{"id":"d","text":"Ray of Light","is_correct":true}],"explanation":"Ray of Light, produced with William Orbit, won four Grammys and is often called her most acclaimed album."},{"id":"q6","question":"What was the name of Madonna''s 1990 tour famous for the conical corsets designed by Jean Paul Gaultier?","options":[{"id":"a","text":"The Girlie Show","is_correct":false},{"id":"b","text":"Blond Ambition World Tour","is_correct":true},{"id":"c","text":"Who''s That Girl World Tour","is_correct":false},{"id":"d","text":"Drowned World Tour","is_correct":false}],"explanation":"The Blond Ambition Tour mixed theatre and pop spectacle and inspired the documentary Truth or Dare."},{"id":"q7","question":"Madonna''s 1989 video with burning crosses drew condemnation from the Vatican. Which song was it for?","options":[{"id":"a","text":"''Papa Don''t Preach''","is_correct":false},{"id":"b","text":"''Material Girl''","is_correct":false},{"id":"c","text":"''Like a Prayer''","is_correct":true},{"id":"d","text":"''Frozen''","is_correct":false}],"explanation":"The ''Like a Prayer'' video cost her a Pepsi sponsorship and became one of pop''s great controversies."},{"id":"q8","question":"Which 2005 album, built as a nonstop dancefloor set, includes ''Hung Up''?","options":[{"id":"a","text":"Hard Candy","is_correct":false},{"id":"b","text":"Confessions on a Dance Floor","is_correct":true},{"id":"c","text":"MDNA","is_correct":false},{"id":"d","text":"Madame X","is_correct":false}],"explanation":"Confessions on a Dance Floor was mixed like a DJ set; ''Hung Up'' samples ABBA''s ''Gimme! Gimme! Gimme!''."}]'::jsonb,
  null,
  array['madonna', 'music', 'pop', 'trivia']::text[],
