  '[{"id":"q1","question":"In which city did The Rolling Stones form in 1962?","options":[{"id":"a","text":"Liverpool","is_correct":false},{"id":"b","text":"London","is_correct":true},{"id":"c","text":"Manchester","is_correct":false},{"id":"d","text":"New York","is_correct":false}],"explanation":"They played their first gig at the Marquee Club in London in July 1962."},{"id":"q2","question":"Who has been the band''s lead singer since the very beginning?","options":[{"id":"a","text":"Keith Richards","is_correct":false},{"id":"b","text":"Brian Jones","is_correct":false},{"id":"c","text":"Ronnie Wood","is_correct":false},{"id":"d","text":"Mick Jagger","is_correct":true}],"explanation":"Mick Jagger has fronted the Stones since 1962; Richards plays guitar and Wood joined in 1975."},{"id":"q3","question":"Which 1965 single became their first No. 1 in the United States?","options":[{"id":"a","text":"''(I Can''t Get No) Satisfaction''","is_correct":true},{"id":"b","text":"''Paint It Black''","is_correct":false},{"id":"c","text":"''Get Off of My Cloud''","is_correct":false},{"id":"d","text":"''Ruby Tuesday''","is_correct":false}],"explanation":"''Satisfaction'' topped the Billboard chart in July 1965 and remains their signature song."},{"id":"q4","question":"On which 1971 album did the famous tongue-and-lips logo first appear?","options":[{"id":"a","text":"Beggars Banquet","is_correct":false},{"id":"b","text":"Exile on Main St.","is_correct":false},{"id":"c","text":"Sticky Fingers","is_correct":true},{"id":"d","text":"Some Girls","is_correct":false}],"explanation":"John Pasche designed the tongue logo, which debuted on Sticky Fingers and became the band''s emblem."},{"id":"q5","question":"Which founding member named the band after a Muddy Waters song and died in 1969?","options":[{"id":"a","text":"Bill Wyman","is_correct":false},{"id":"b","text":"Brian Jones","is_correct":true},{"id":"c","text":"Ian Stewart","is_correct":false},{"id":"d","text":"Charlie Watts","is_correct":false}],"explanation":"Brian Jones took the name from Muddy Waters'' ''Rollin'' Stone''; he died in July 1969, weeks after leaving the band."},{"id":"q6","question":"Which 1969 album opens with ''Gimme Shelter'' and closes with ''You Can''t Always Get What You Want''?","options":[{"id":"a","text":"Beggars Banquet","is_correct":false},{"id":"b","text":"Aftermath","is_correct":false},{"id":"c","text":"Let It Bleed","is_correct":true},{"id":"d","text":"Sticky Fingers","is_correct":false}],"explanation":"Let It Bleed bookends those two classics, both featuring singer Merry Clayton''s famous guest vocal on ''Gimme Shelter''."},{"id":"q7","question":"Who was the band''s drummer from 1963 until his death in 2021?","options":[{"id":"a","text":"Charlie Watts","is_correct":true},{"id":"b","text":"Mick Avory","is_correct":false},{"id":"c","text":"Keith Moon","is_correct":false},{"id":"d","text":"Steve Jordan","is_correct":false}],"explanation":"Charlie Watts held the drum seat for 58 years; Steve Jordan became the touring drummer after his death."},{"id":"q8","question":"Which 1981 hit opens the Tattoo You album and became a concert staple?","options":[{"id":"a","text":"''Miss You''","is_correct":false},{"id":"b","text":"''Angie''","is_correct":false},{"id":"c","text":"''Brown Sugar''","is_correct":false},{"id":"d","text":"''Start Me Up''","is_correct":true}],"explanation":"''Start Me Up'' opens Tattoo You and has opened dozens of Stones shows ever since."}]'::jsonb,
